use std::fs
use std::collections::BTreeMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut accts: BTreeMap<string, int> = BTreeMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "balance" {
            let b = accts.get(parts[1])
            match b {
                Some(v) => println("${v}"),
                None => println("error: unknown account ${parts[1]}"),
            }
        } else if cmd == "open" {
            let amt: int = parts[2].parse::<int>().unwrap_or(-1)
            if amt < 0 {
                println("error: invalid amount")
            } else if accts.contains_key(parts[1]) {
                println("error: duplicate account")
            } else {
                accts.insert(parts[1], amt)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                let cur = accts.get(parts[1])
                match cur {
                    None => println("error: unknown account ${parts[1]}"),
                    Some(v) => {
                        if cmd == "deposit" {
                            accts.insert(parts[1], v + amt)
                            println("ok")
                        } else if v < amt {
                            println("error: insufficient funds")
                        } else {
                            accts.insert(parts[1], v - amt)
                            println("ok")
                        }
                    }
                }
            }
        } else if cmd == "transfer" {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !accts.contains_key(parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else if !accts.contains_key(parts[2]) {
                println("error: unknown account ${parts[2]}")
            } else if parts[1] == parts[2] {
                println("error: same account")
            } else {
                let a: int = accts.get(parts[1]).unwrap_or(0)
                let b: int = accts.get(parts[2]).unwrap_or(0)
                if a < amt {
                    println("error: insufficient funds")
                } else {
                    accts.insert(parts[1], a - amt)
                    accts.insert(parts[2], b + amt)
                    println("ok")
                }
            }
        }
    }
    for (k, v) in accts {
        println("${k} ${v}")
    }
}

